function todayIso() { const today = new Date(); return new Date(today.getTime() - today.getTimezoneOffset() * 60_000).toISOString().slice(0, 10) }
function formatDate(date: string) { return new Intl.DateTimeFormat('en-NG', { dateStyle: 'long', timeZone: 'UTC' }).format(new Date(`${date}T00:00:00Z`)) }
function formatTime(timestamp: string) { return new Intl.DateTimeFormat('en-NG', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(timestamp)) }
function statusClass(status: CommitmentStatus) { return `status status--${status.toLowerCase().replaceAll(' ', '-')}` }
function agreementClass(status: string) { return `agreement-chip agreement-chip--${status.toLowerCase().replaceAll(' ', '-').replace('—', '')}` }
function FieldError({ id, children }: { id: string, children?: string }) { return children ? <p className="field-error" id={id}>{children}</p> : null }

function ChargeForm({ state, existing, onSave, onCancel }: { state: WorkflowState, existing?: ChargeProposal, onSave: (next: WorkflowState) => void, onCancel: () => void }) {
  const id = useId(), [name, setName] = useState(existing?.name ?? ''), [amount, setAmount] = useState(existing ? String(formatKobo(existing.amountKobo)) : ''), [purpose, setPurpose] = useState(existing?.purpose ?? ''), [refundable, setRefundable] = useState(existing?.refundable ? 'yes' : 'no'), [landlordName, setLandlordName] = useState(existing?.landlordName ?? ''), [errors, setErrors] = useState<Errors>({})
  const submit = (event: FormEvent) => { event.preventDefault(); const next: Errors = {}, amountKobo = parseNairaToKobo(amount); if (name.trim().length < 3) next.name = 'Enter a meaningful charge name.'; if (!amountKobo) next.amount = 'Enter a positive naira amount with no more than two decimal places.'; if (purpose.trim().length < 3) next.purpose = 'Enter a meaningful purpose or explanation.'; if (!landlordName.trim()) next.landlord = 'Enter the landlord’s name.'; if (Object.keys(next).length) return setErrors(next); onSave(saveChargeProposal(state, { id: existing?.id ?? `charge-${Date.now()}`, name: name.trim(), amountKobo: amountKobo!, purpose: purpose.trim(), refundable: refundable === 'yes', landlordName: landlordName.trim() }, new Date().toISOString())) }
  return <form className="workflow-form charge-form" onSubmit={submit} noValidate><div className="inspection-form-heading"><div><p className="form-kicker">{existing ? 'Edit charge proposal' : 'Add charge proposal'}</p><h4>{existing?.name ?? 'New rental charge'}</h4></div><button className="text-button" type="button" onClick={onCancel}>Cancel</button></div><div className="form-grid"><div className="field-group"><label htmlFor={`${id}-name`}>Charge name</label><input id={`${id}-name`} value={name} onChange={(e) => setName(e.target.value)} aria-invalid={Boolean(errors.name)} /><FieldError id={`${id}-name-error`}>{errors.name}</FieldError></div><div className="field-group"><label htmlFor={`${id}-amount`}>Amount in naira</label><input id={`${id}-amount`} inputMode="decimal" value={amount} onChange={(e) => setAmount(e.target.value)} aria-invalid={Boolean(errors.amount)} /><FieldError id={`${id}-amount-error`}>{errors.amount}</FieldError></div><div className="field-group full-field"><label htmlFor={`${id}-purpose`}>Purpose or explanation</label><textarea id={`${id}-purpose`} rows={3} value={purpose} onChange={(e) => setPurpose(e.target.value)} aria-invalid={Boolean(errors.purpose)} /><FieldError id={`${id}-purpose-error`}>{errors.purpose}</FieldError></div><fieldset className="field-group result-fieldset"><legend>Refundable</legend><div className="radio-options"><label><input type="radio" name={`${id}-refundable`} checked={refundable === 'yes'} onChange={() => setRefundable('yes')} /> Yes</label><label><input type="radio" name={`${id}-refundable`} checked={refundable === 'no'} onChange={() => setRefundable('no')} /> No</label></div></fieldset><div className="field-group"><label htmlFor={`${id}-landlord`}>Landlord name</label><input id={`${id}-landlord`} value={landlordName} onChange={(e) => setLandlordName(e.target.value)} aria-invalid={Boolean(errors.landlord)} /><FieldError id={`${id}-landlord-error`}>{errors.landlord}</FieldError></div></div><button className="primary-button" type="submit">Submit and approve proposal</button></form>
}

